export function writeHeadToBFCache(
  now: number,
  varyPath: SegmentVaryPath,
  head: React.ReactNode,
  prefetchHead: React.ReactNode,
  dynamicStaleAt: number,
  bfcacheId: number
): void {
  // Read the special "segment" that represents the head data.
  writeToBFCache(
    now,
    varyPath,
    head,
    prefetchHead,
    null,
    null,
    dynamicStaleAt,
    bfcacheId
